  PanelText_UI_Events_2ndAnnivWB_StageGroup_Text_C_Introduction_Content = {
    Text = "Venite! Con la follia, la carneficina e l'agonia come note, intoniamo questo requiem che scintilla fra le stelle!\nQuel Dio Cieco e Idiota, l'Essere Supremo della Stoltezza e del Caos, non deve risvegliarsi, né ora né in futuro."
