  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Introduction_Content = {
    Text = "Le luci si accendono. L'applauso si spegne. Il pubblico attende con trepidazione.\nÈ ora di salire sul palco, miei cari bambini. Avanti — esibitevi, squarciate le vostre anime e vendete i vostri segreti più profondi. Prendete le vostre ferite più devastanti e trasformatele in dolci per il piacere del pubblico. Crogiolatevi avidamente in quell'unico fascio di luce acceso solo per voi, finché il sipario non calerà a seppellire voi e il vostro pubblico insieme.\n\nQuesto è il palcoscenico a cui eravate destinati — salite! Non abbiate paura; non c'è bisogno di tremare."
  },
