  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Introduction_Content = {
    Text = "♪~~♫~~♪~~♫~~♪~~♫~~\nSotto la montagna innevata, ogni guida la ricorda e ogni bambino la canta ancora. Lei è la volontà della montagna maestosa fatta carne, lei è la misericordiosa dea Umapati. Il suo potere divino è sparso per il mondo mortale; i suoi tesori non possono essere trovati. Sono abbastanza vicini da toccare; non lasciano alcuna traccia. \nAbbandona qualcosa. Tieni stretto qualcosa. Chiunque abbia il cuore falso verso la vera forma della dea sarà sepolto nella montagna innevata per sempre, insieme alla montagna che è morta."
  },
