  },
  PanelText_UI_Events_Panel_Castor_StageGroup_Text_C_Introduction_Content = {
    Text = "La vita di un uccello è destinata a essere una vita di libertà. Avreste dovuto vederlo nel momento della schiusa, strappare la libertà della vita dalle mani della morte. Avreste dovuto vederlo quando imparò a volare per la prima volta, strappare la libertà della sopravvivenza dal conforto di un nido caldo. Ora, se la Chiave della libertà fosse gettata nell'abisso della morte, si lancerebbe senza esitazione — scegliendo di affrontare la tempesta furiosa della morte piuttosto che una vita angusta, abbracciando invece l'infinita libertà."
  },
