  PanelText_UI_Events_Panel_Clementine_StageGroup_Text_C_Introduction_Content = {
    Text = "Da allora, non ha più versato una sola lacrima.\nVagando sola, alla deriva in un mondo colmo di reietti.\nUn piano grandioso sta per avere inizio, come il suo ultimo addio.\nÈ la psicologa di maggior successo, e questo è il suo trattamento più riuscito."
