  PanelText_UI_Events_Panel_Daffodil_StageGroup_Text_C_Introduction_Content = {
    Text = "In questa cittadina costiera si trova una vivace via commerciale. Il commercio marittimo ha portato qui innumerevoli merci alla moda; purché si paghino abbastanza Fiorini Leoniani, si possono sempre trovare prodotti soddisfacenti.\nL'unica eccezione è un piccolo negozio all'angolo, un luogo pittoresco colmo di antichità magiche. Tra il fumo che si leva da una pipa, il negoziante, con un cappello a tesa larga, ti rivolgerà lentamente un sorriso.\n\"Benvenuto al Negozio Senza Pensieri, dove ogni tuo bisogno può essere soddisfatto, purché tu offra un compenso adeguato...\"\n\"Naturalmente, naturalmente, i prezzi sono equi, e siamo onesti con tutti.\""
  },
