  PanelText_UI_Events_Panel_KathiguRa_StageGroup_Text_C_Introduction_Content = {
    Text = "Lei si erge ancora una volta sulla Terra, e la vendetta che tutto consuma giunge come promesso.\n\nÈ una Caccia senza fine, è il fuoco ardente della Fiamma Vivente.\n\nLei attraverserà ogni angolo, dando la caccia a tutti coloro che hanno firmato un Contratto con la Morte.\n\nCorri, corri, fuggi nelle Tenebre più profonde, fuggi in un luogo dove credi di non poter essere trovato.\n\nAnche se è inutile, poiché Egli calpesterà ogni mondo.\n\nEgli darà la caccia a ogni cosa finché tutto non sarà ridotto in cenere."
  },
