  PanelText_UI_Events_Panel_Mosk_StageGroup_Text_C_Introduction_Content = {
    Text = "Cielo~ così luminoso~ mare~ così calmo~\nVortice~ e amici~ Coalsie~ salpiamo!\nTempeste? Nessuna paura! Fulmini? Nessuna paura!\nVortice, amici, Coalsie~\nPer la nostra libertà! Pronti! Via!"
  },
