  PanelText_UI_Events_Panel_Mouchette_StageGroup_Text_C_Introduction_Content = {
    Text = "Un giorno, ti rendi improvvisamente conto di essere cambiata.\nNessuno l'ha scoperto perché hai lo stesso comportamento e lo stesso portamento, lo stesso aspetto incantevole.\nMa sai benissimo che il cuore un tempo rosso brillante è già stato coperto da una maschera fatta di nebbia.\nSe riesco a continuare a fingere, sono ancora la stessa persona di prima?\nCongratulazioni, questa domanda non è rimasta nella tua mente per più di un secondo; in effetti, prima che quella maschera venga sollevata, nessuno conosce i tuoi veri pensieri.\nAllora, partiamo~"
  },
