  PanelText_UI_Events_Panel_OriDoll_StageGroup_Text_C_Introduction_Content = {
    Text = "Contempla il grande Portale alla fine del mondo, poi avanza senza esitazione.\nClic. La maniglia gira. I Suoi Occhi cercano avidamente oltre la soglia.\nMa non vi è che il nulla. È entrata nell'Illusione.\nAvrebbe dovuto saperlo: i doni offerti con tanta generosità esigono sempre il prezzo più alto."
