  PanelText_UI_Events_Panel_Pickman_StageGroup_Text_C_Introduction_Content = {
    Text = "Tra la sanità mentale e il Crollo, un bizzarro rotolo si dispiega.\nLe allucinazioni che disprezzi dipingono colori brillanti,\nLa perdita di controllo che temi assume la forma della Lealtà.\nQui, la Follia è l'istinto dell'arte, l'origine del mondo,\nL'unica verità che non mente mai."
