  PanelText_UI_Events_Panel_Pollux_StageGroup_Text_C_Introduction_Content = {
    Text = "Odio e amore, calore e dolore, ciò che un tempo stringevamo e ciò che abbiamo perduto — tutto è intrecciato ora, impossibile da districare.\nLascia che il nostro sangue condiviso scorra insieme e confluisca, forgiando il nostro destino inscindibile."
