  PanelText_UI_Events_Panel_Pontos_StageGroup_Text_C_Introduction_Content = {
    Text = "Quando l'infausto bagliore bianco trafigge ancora una volta le finestre dell'Alta Casa, lui ti ha già rivolto il suo invito.\nAccogliere, inghiottire, avvolgere, stringere… \nRispondi al Richiamo proveniente dalle profondità del Mare Profondo, unisciti a questa caccia senza fine — il tuo passato, il tuo sé, tutto ciò ha ormai perso ogni importanza."
