  PanelText_UI_Events_Panel_Saya_StageGroup_Text_C_Introduction_Content = {
    Text = "Scienza? Irrilevante. Etica? Irrilevante. Moralità? Irrilevante. \nVita, morte, speranza, disperazione... alla fine, su un quaderno nel seminterrato, la stessa dimostrazione è scritta da due mani diverse. \nDicono: <Italic:\"Guarda—l'amore è l'unico ed eterno tema.\">"
