    Text = [[
Il Vecchio Sestante determina gli angoli tra le stelle, antiche carte nautiche delineano la rotta prevista, e la bussola consunta decide la direzione in cui procedere...
Persino nel profondo e gelido Mar Nero, ci sono ancora Esploratori che si affidano a rame e ferro comuni per indicare la via a Tutti.
